#!/usr/bin/env bash
# ghorg reclone post_exec_script for a generic workspace.
# Generated by the ghorg-create-vscode-generic-workspace skill.
#
# ghorg clones the repos into BASE_DIR/PREFIX-generic-workspace. This script
# renames that directory to BASE_DIR/PREFIX-<name> so every run produces a new,
# independent workspace, then prepares it for VS Code.
#
# ghorg calls this script with two arguments: the clone status (success or fail)
# and the name of the reclone entry.

PREFIX="__PREFIX__"
BASE_DIR="__BASE_DIR__"
OPEN_IN_VSCODE="true"

# Files to copy into each new workspace, one "source|destination" entry per line.
# The destination is relative to the workspace root.
COPY_FILES=(
)

STATUS="$1"
RECLONE_NAME="$2"
STAGING_DIR="$BASE_DIR/${PREFIX}-generic-workspace"
MARKER_FILE=".ghorg-generic-workspace"

echo ""
echo "********** post-exec logs **********"

if [ "$STATUS" != "success" ]; then
  echo "ERROR: clone did not succeed (status=$STATUS); skipping workspace setup"
  echo ""
  exit 1
fi

if [ ! -d "$STAGING_DIR" ]; then
  echo "ERROR: expected workspace directory $STAGING_DIR not found; aborting"
  echo ""
  exit 1
fi

# Take the name from GENERIC_WORKSPACE_NAME when set so a workspace can be
# created without a terminal (for example by an agent). Otherwise prompt on
# /dev/tty because ghorg does not connect stdin to this script.
RAW_NAME="$GENERIC_WORKSPACE_NAME"
if [ -z "$RAW_NAME" ]; then
  if ! { : < /dev/tty; } 2> /dev/null; then
    echo "ERROR: no terminal available to prompt for a workspace name; set GENERIC_WORKSPACE_NAME instead"
    echo ""
    exit 1
  fi
  printf "Enter a name for this %s workspace: " "$PREFIX" > /dev/tty
  read -r RAW_NAME < /dev/tty
fi

# Slugify: lowercase, collapse non-alphanumeric runs to a single hyphen, trim hyphens.
SLUG=$(printf '%s' "$RAW_NAME" | tr '[:upper:]' '[:lower:]' | sed -E 's/[^a-z0-9]+/-/g; s/^-+//; s/-+$//')
if [ -z "$SLUG" ]; then
  echo "ERROR: name was empty after sanitizing; aborting"
  echo ""
  exit 1
fi

NEW_NAME="${PREFIX}-${SLUG}"
WORKSPACE_DIR="$BASE_DIR/$NEW_NAME"

if [ -e "$WORKSPACE_DIR" ]; then
  echo "ERROR: $WORKSPACE_DIR already exists; run again with a different name"
  echo ""
  exit 1
fi

if ! mv "$STAGING_DIR" "$WORKSPACE_DIR"; then
  echo "ERROR: could not rename $STAGING_DIR to $WORKSPACE_DIR"
  echo ""
  exit 1
fi
echo "INFO: Renamed workspace directory to $WORKSPACE_DIR"

# The marker lets the ghorg-cleanup-vscode-generic-workspace skill find workspaces
# created from this template without guessing from directory names.
printf 'prefix=%s\nreclone=%s\ncreated=%s\n' "$PREFIX" "$RECLONE_NAME" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "$WORKSPACE_DIR/$MARKER_FILE"

# A git repo at the workspace root gives editors and tools a single project
# root instead of walking up into the parent directory.
git init -q "$WORKSPACE_DIR"

WORKSPACE_FILE="$WORKSPACE_DIR/${NEW_NAME}.code-workspace"
cat > "$WORKSPACE_FILE" <<'EOF'
{
    "folders": [
        {
            "path": "."
        }
    ],
    "settings": {}
}
EOF
echo "INFO: Created VS Code workspace file at $WORKSPACE_FILE"

for entry in "${COPY_FILES[@]}"; do
  src="${entry%%|*}"
  dest="$WORKSPACE_DIR/${entry#*|}"
  if [ ! -f "$src" ]; then
    echo "WARN: $src not found; skipping copy"
    continue
  fi
  mkdir -p "$(dirname "$dest")" && cp "$src" "$dest" && echo "INFO: Copied $src to $dest"
done

if [ "$OPEN_IN_VSCODE" = "true" ]; then
  # ghorg runs this script in a non-interactive shell where a `code` shell
  # function or alias is not defined, so fall back to the macOS app bundle,
  # then to `open`.
  MAC_CODE_BIN="/Applications/Visual Studio Code.app/Contents/Resources/app/bin/code"
  if command -v code > /dev/null 2>&1; then
    code "$WORKSPACE_DIR"
    echo "INFO: Opened $WORKSPACE_DIR in VS Code"
  elif [ -x "$MAC_CODE_BIN" ]; then
    "$MAC_CODE_BIN" "$WORKSPACE_DIR"
    echo "INFO: Opened $WORKSPACE_DIR in VS Code"
  elif [ "$(uname)" = "Darwin" ] && open -b com.microsoft.VSCode "$WORKSPACE_DIR" 2> /dev/null; then
    echo "INFO: Opened $WORKSPACE_DIR in VS Code (via open)"
  else
    echo "WARN: could not locate VS Code; open $WORKSPACE_DIR manually"
  fi
fi

echo "INFO: Workspace ready at $WORKSPACE_DIR"
echo ""
